        long id=candidate(collect(incoming("iPhone 18 Pro 待核对","review","name")));var revise=resolution(id,"revise");revise.put("componentText","iPhone 18 Pro");revise.put("classification","missing");revise.put("reviewReason","");tx.execute(status->intake.resolve(id,previewed(id,revise),null));
