    @Test void seventyOneCandidateCollectionAndReplayUseConstantCatalogDetailCallsAndCompactAudit(){
        var command=identity();var entries=new ArrayList<Map<String,Object>>();for(int index=1;index<=71;index++)entries.add(values("supplierIndex",2L,"componentText","QA人工缺档型号 "+index,"brandId",1L,"classification","missing","reviewReason","","reason","QA明确人工整理片段"));command.put("entries",entries);command.put("requestId",UUID.randomUUID().toString());var preview=tx.execute(status->intake.sourcePreview(command));assertEquals(71L,number(map(preview.get("summary")).get("entryCount")));command.put("previewToken",preview.get("previewToken"));String before=rawRow(row);clearInvocations(catalog);
        var result=tx.execute(status->intake.collect(command,null));assertEquals(71,maps(result.get("items")).size());assertEquals(71L,number(result.get("addedSourceCount")));assertEquals(71,count("plm_phone_model_intake"));assertEquals(71,count("plm_phone_model_intake_source"));assertTrue(maps(result.get("items")).stream().noneMatch(item->item.containsKey("sources")));verify(catalog,times(2)).detail(anyString(),anyLong(),anyString(),anyString());assertEquals(before,rawRow(row));assertEquals(1,count("plm_phone_model_member"));assertEquals(1,count("plm_code_item"));
        var logged=decode(json,jdbc.queryForObject("select detail_json from plm_operation_log where business_type='PHONE_MODEL_INTAKE' order by log_id desc limit 1",String.class));assertEquals(71,maps(map(logged.get("after")).get("evidenceChanges")).size());assertFalse(map(logged.get("after")).containsKey("sourcePreview"));assertTrue(maps(map(logged.get("result")).get("items")).stream().allMatch(item->item.keySet().equals(Set.of("id"))));clearInvocations(catalog);
        var replay=tx.execute(status->intake.collect(command,null));assertEquals(true,replay.get("replayed"));assertEquals(71,maps(replay.get("items")).size());verify(catalog,times(1)).detail(anyString(),anyLong(),anyString(),anyString());assertEquals(71,count("plm_phone_model_intake_source"));assertEquals(1,jdbc.queryForObject("select count(*) from plm_operation_log where business_type='PHONE_MODEL_INTAKE'",Long.class));
    }
    @Test void everyResolutionActionWithPartiallyHiddenSourcesIsBlockedForPreviewAndDirectConfirmation(){
        long id=candidate(collect(incoming("iPhone 18 Pro","missing","")));addHiddenEvidence(id);String candidateBefore=jdbc.queryForObject("select to_jsonb(c)::text from plm_phone_model_intake c where id=?",String.class,id),sourceBefore=rawRow(row),otherBefore=rawRow(sibling);long audits=count("plm_operation_log"),events=count("plm_partner_event"),phones=count("plm_phone_model_member"),codes=count("plm_code_item");
        for(String action:List.of("create","link","revise","defer","reopen")){var command=resolution(id,action);if(action.equals("link"))command.put("phoneModelIds",List.of(12L));if(action.equals("revise"))command.put("componentText","iPhone 18 Pro QA revised");var preview=tx.execute(status->intake.resolutionPreview(id,command));assertEquals(false,preview.get("canSave"),action);assertTrue(stringsForAssertion(preview.get("blockers")).stream().anyMatch(message->message.contains("不能修改候选")),action);command.put("previewToken",preview.get("previewToken"));assertThrows(RuntimeException.class,()->tx.execute(status->intake.resolve(id,command,null)),action);assertEquals(candidateBefore,jdbc.queryForObject("select to_jsonb(c)::text from plm_phone_model_intake c where id=?",String.class,id),action);assertEquals(sourceBefore,rawRow(row),action);assertEquals(otherBefore,rawRow(sibling),action);assertEquals(audits,count("plm_operation_log"),action);assertEquals(events,count("plm_partner_event"),action);assertEquals(phones,count("plm_phone_model_member"),action);assertEquals(codes,count("plm_code_item"),action);}
    }
    private List<String> stringsForAssertion(Object value){return ((List<?>)value).stream().map(String::valueOf).toList();}
